import type { Exercise, ReadingPassage } from "../types";

const createdAt = "2026-08-02T00:00:00.000Z";

function question(
  id: string,
  passageId: string,
  topic: string,
  prompt: string,
  options: string[],
  correctAnswer: string,
  explanation: string,
): Exercise {
  return {
    id,
    passageId,
    type: "reading",
    section: "reading",
    topic,
    difficulty: "b2",
    level: "B2",
    question: prompt,
    instructions: "Scegli la risposta sostenuta dal testo, non solo quella plausibile.",
    options: options.map((label, index) => ({ id: String(index), label })),
    correctAnswer,
    explanation,
    examples: [],
    tags: ["reading", "b2", topic],
    estimatedTime: 90,
    source: "original",
    createdAt,
  };
}

